  try {
    if (new TextEncoder().encode(text).length > 65536) throw 0;
    const value: unknown = JSON.parse(text);
    if (!object(value)) throw 0;
    for (const key of Object.keys(value))
      if (!['format', 'snapshot', 'tournament', 'version'].includes(key))
        return { tournament: null, snapshot: null, error: `Unknown field: ${key}.` };
    if (
      !keys(value, ['format', 'snapshot', 'tournament', 'version']) ||
      value.format !== 'neon-pairs/tournament' ||
      value.version !== 1 ||
      (value.tournament !== null && !validateTournament(value.tournament))
    )
      throw 0;
    const snapshot = value.snapshot === null ? null : JSON.stringify(value.snapshot);
    if (snapshot) {
      const game = decodeSnapshot(snapshot);
      const t = value.tournament as Tournament | null;
      if (
        !game ||
        isWon(game) ||
        !t ||
        t.matches[t.index]!.winner !== null ||
        game.boardCode !== t.matches[t.index]!.boardCode
      )
        throw 0;
    }
    return { tournament: value.tournament as Tournament | null, snapshot, error: '' };
  } catch {
    return { tournament: null, snapshot: null, error: 'Invalid tournament.' };
  }
