const KEY = 'np3:tournaments';
function readHistory(): { items: Tournament[]; blocked: boolean } {
  try {
    const text = localStorage.getItem(KEY);
    if (!text) return { items: [], blocked: false };
    const value: unknown = JSON.parse(text);
    if (typeof value !== 'object' || value === null || Array.isArray(value))
      return { items: [], blocked: false };
    const data = value as Record<string, unknown>;
    if (
      Object.keys(data).length !== 2 ||
      data.v !== 3 ||
      !Array.isArray(data.items) ||
      data.items.length > 10 ||
      !data.items.every(
        (item: unknown) =>
          validateTournament(item) &&
          item.index === item.matches.length - 1 &&
          item.matches[item.index]!.winner !== null,
      )
    )
      return { items: [], blocked: false };
    return { items: data.items as Tournament[], blocked: false };
  } catch (error) {
    return { items: [], blocked: !(error instanceof SyntaxError) };
  }
